const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define the North Crimean Canal area in Ukraine
  const canalRegion = ee.Geometry.Polygon([
    [[33.5, 45.5], [34.5, 45.5], [34.5, 46.2], [33.5, 46.2], [33.5, 45.5]]
  ]);

  // 2. Cloud masking function for Sentinel-2
  function maskS2clouds(image) {
    const qa = image.select('QA60');
    const cloudBitMask = 1 << 10;
    const cirrusBitMask = 1 << 11;
    const mask = qa.bitwiseAnd(cloudBitMask).eq(0)
      .and(qa.bitwiseAnd(cirrusBitMask).eq(0));
    return image.updateMask(mask);
  }

  // 3. Function to calculate water extent using MNDWI
  function calculateWaterExtent(startDate, endDate, label) {
    const collection = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
      .filterBounds(canalRegion)
      .filterDate(startDate, endDate)
      .map(maskS2clouds);

    const count = collection.size().getInfo();
    console.log(`${label} - Images found: ${count}`);

    if (count === 0) {
      return null;
    }

    const image = collection.median();

    // Calculate MNDWI: (Green - SWIR) / (Green + SWIR)
    const mndwi = image.normalizedDifference(['B3', 'B11']).rename('MNDWI');

    // Water is typically MNDWI > 0
    const waterMask = mndwi.gt(0);

    // Count valid pixels
    const pixelCount = waterMask.reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: canalRegion,
      scale: 1000,
      maxPixels: 1e9
    }).get('MNDWI').getInfo();

    console.log(`${label} - Valid pixels after masking: ${pixelCount}`);

    if (pixelCount === 0) {
      return { pixels: 0, waterExtent: 0 };
    }

    // Calculate water extent (sum of water pixels)
    const waterExtent = waterMask.reduceRegion({
      reducer: ee.Reducer.sum(),
      geometry: canalRegion,
      scale: 1000,
      maxPixels: 1e9
    }).get('MNDWI').getInfo();

    return { pixels: pixelCount, waterExtent: waterExtent };
  }

  // 4. Calculate water extent for both dates
  const june3 = calculateWaterExtent('2023-06-01', '2023-06-05', 'June 3');

  if (june3 === null) {
    console.log('No images found for June 3, 2023');
    console.log('<answer>C1</answer>');
    return;
  }

  if (june3.pixels === 0) {
    console.log('No valid pixels for June 3 after cloud masking');
    console.log('<answer>C2</answer>');
    return;
  }

  const july19 = calculateWaterExtent('2023-07-17', '2023-07-21', 'July 19');

  if (july19 === null) {
    console.log('No images found for July 19, 2023');
    console.log('<answer>C1</answer>');
    return;
  }

  if (july19.pixels === 0) {
    console.log('No valid pixels for July 19 after cloud masking');
    console.log('<answer>C2</answer>');
    return;
  }

  // 5. Validate and compare
  if (june3.waterExtent === null || july19.waterExtent === null || 
      isNaN(june3.waterExtent) || isNaN(july19.waterExtent)) {
    console.log('Calculation failed - invalid values');
    console.log('<answer>C3</answer>');
    return;
  }

  console.log(`June 3 water extent: ${june3.waterExtent.toFixed(0)} pixels`);
  console.log(`July 19 water extent: ${july19.waterExtent.toFixed(0)} pixels`);

  const decrease = july19.waterExtent < june3.waterExtent;
  const percentChange = ((july19.waterExtent - june3.waterExtent) / june3.waterExtent * 100).toFixed(1);

  console.log(`Change: ${percentChange}%`);

  if (decrease) {
    console.log('<answer>A</answer>');
  } else {
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
